h1, h2, h3 {
  font-family: Arial, sans-serif;
  color: navy;
}

a:hover {
  color: red;
}

input:focus {
  border-color: blue;
}

li:first-child {
  font-weight: bold;
}

li:nth-child(even) {
  background-color: #f5f5f5;
}

p {
  color: red;     /* вес: 0-0-1 */
}

.text {
  color: blue;    /* вес: 0-1-0 — побеждает */
}

#special {
  color: green;   /* вес: 1-0-0 — побеждает */
}

.btn {
  color: red;
}

.btn {
  color: blue;  /* побеждает — написано ниже */
